using EmployeeMonitoringAPI.Data;
using EmployeeMonitoringAPI.DTOs;
using EmployeeMonitoringAPI.Helpers;
using EmployeeMonitoringAPI.Interfaces;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace EmployeeMonitoringAPI.Controllers;
[Route("api/[controller]")][ApiController][Authorize(Roles="Admin")]
public sealed class ReportsController:ControllerBase
{
 private readonly ApplicationDbContext _db;private readonly IAuditService _audit;public ReportsController(ApplicationDbContext db,IAuditService audit){_db=db;_audit=audit;}
 [HttpGet("summary")]
 public async Task<ActionResult<AdminReportSummaryDto>> Summary([FromQuery]AdminReportQuery query){var(from,to)=ReportDateRange.Resolve(query);var projects=await ProjectQuery(query).Where(x=>x.CreatedAt>=from&&x.CreatedAt<to).ToListAsync();var completed=projects.Count(x=>x.Status=="Completed");return Ok(new AdminReportSummaryDto{ProjectsCreated=projects.Count,ProjectsStarted=projects.Count(x=>x.StartDate>=from&&x.StartDate<to),ProjectsCompleted=completed,ProjectsOngoing=projects.Count(x=>x.Status=="Ongoing"),ProjectsDelayed=projects.Count(x=>x.Status=="Delayed"||(x.EndDate<DateTime.UtcNow&&x.Status!="Completed")),ProjectsArchived=projects.Count(x=>x.IsArchived),CompletionRate=projects.Count==0?0:Math.Round((decimal)completed/projects.Count*100,2),AverageProgress=projects.Count==0?0:Math.Round((decimal)projects.Average(x=>x.ProgressPercentage),2),ManagerAssignments=projects.Count(x=>x.ManagerId.HasValue),DepartmentCount=projects.Where(x=>x.DepartmentId.HasValue).Select(x=>x.DepartmentId).Distinct().Count()});}
 [HttpGet("{type}/export")]
 public async Task<IActionResult> Export(string type,[FromQuery]AdminReportQuery query,string format="csv"){if(!format.Equals("csv",StringComparison.OrdinalIgnoreCase))return BadRequest(new{message="CSV is the supported Admin export format"});if(query.From.HasValue&&query.To.HasValue&&query.From.Value.Date>query.To.Value.Date)return BadRequest(new{message="From date cannot be after to date"});var supported=new[]{"department-summary","manager-assignments","project-status","project-progress","delayed-projects","projects-without-managers","departments-without-managers","quarterly-projects","attendance-summary","leave-summary","calendar-summary","system-activity","audit-logs"};if(!supported.Contains(type,StringComparer.OrdinalIgnoreCase))return BadRequest(new{message="Unsupported Admin report type"});var rows=await BuildRows(type,query);var headers=rows.FirstOrDefault()?.Keys.ToArray()??new[]{"Message"};if(rows.Count==0)rows.Add(new(){{"Message","No records found"}});var bytes=CsvSecurity.Build(headers,rows.Select(row=>headers.Select(h=>row.GetValueOrDefault(h))));await _audit.RecordAsync("ReportExported","Report",type,safeMetadata:new{Rows=rows.Count,query.Year,query.Quarter});return File(bytes,"text/csv",$"{type}-{DateTime.UtcNow:yyyyMMdd}.csv");}
 private IQueryable<Models.Project> ProjectQuery(AdminReportQuery query){var q=_db.Projects.AsNoTracking().Include(x=>x.Manager).Include(x=>x.Department).AsQueryable();if(!query.IncludeArchived)q=q.Where(x=>!x.IsArchived);if(query.DepartmentId.HasValue)q=q.Where(x=>x.DepartmentId==query.DepartmentId);if(query.ManagerId.HasValue)q=q.Where(x=>x.ManagerId==query.ManagerId);if(!string.IsNullOrWhiteSpace(query.Status))q=q.Where(x=>x.Status==query.Status);return q;}
 private async Task<List<Dictionary<string,string?>>> BuildRows(string type,AdminReportQuery query){var(from,to)=ReportDateRange.Resolve(query);switch(type.ToLowerInvariant()){
  case "department-summary":{var rows=await _db.Departments.AsNoTracking().ToListAsync();return rows.Select(x=>Row(("DepartmentCode",x.DepartmentCode),("Department",x.Name),("Active",x.IsActive.ToString()),("Employees",_db.Users.Count(u=>u.DepartmentId==x.Id&&u.Role=="Employee").ToString()),("Managers",_db.Users.Count(u=>u.DepartmentId==x.Id&&u.Role=="Manager").ToString()),("ActiveProjects",_db.Projects.Count(p=>p.DepartmentId==x.Id&&!p.IsArchived).ToString()))).ToList();}
  case "manager-assignments":{var rows=await _db.Users.AsNoTracking().Include(x=>x.Department).Where(x=>x.Role=="Manager").ToListAsync();return rows.Select(x=>Row(("ManagerCode",x.EmployeeCode),("Manager",x.FullName),("OfficialEmail",x.Email),("Department",x.Department?.Name),("AccountStatus",x.IsActive?"Active":"Inactive"),("AssignedProjects",_db.Projects.Count(p=>p.ManagerId==x.UserId).ToString()),("ActiveProjects",_db.Projects.Count(p=>p.ManagerId==x.UserId&&!p.IsArchived).ToString()))).ToList();}
  case "project-status":case "project-progress":case "delayed-projects":case "projects-without-managers":{var q=ProjectQuery(query);if(type=="delayed-projects")q=q.Where(x=>x.Status=="Delayed"||(x.EndDate<DateTime.UtcNow&&x.Status!="Completed"));if(type=="projects-without-managers")q=q.Where(x=>!x.ManagerId.HasValue);var rows=await q.ToListAsync();return rows.Select(x=>Row(("ProjectCode",x.ProjectCode),("Project",x.ProjectName),("Department",x.Department?.Name),("Manager",x.Manager?.FullName),("Status",x.Status),("Priority",x.Priority),("Progress",x.ProgressPercentage.ToString()),("StartDate",x.StartDate.ToString("yyyy-MM-dd")),("EndDate",x.EndDate.ToString("yyyy-MM-dd")),("Archived",x.IsArchived.ToString()))).ToList();}
  case "departments-without-managers":{var rows=await _db.Departments.AsNoTracking().Where(d=>d.IsActive&&!_db.Users.Any(u=>u.DepartmentId==d.Id&&u.Role=="Manager"&&u.IsActive)).ToListAsync();return rows.Select(x=>Row(("DepartmentCode",x.DepartmentCode),("Department",x.Name),("Active",x.IsActive.ToString()))).ToList();}
  case "quarterly-projects":{var projects=await ProjectQuery(query).Where(x=>x.CreatedAt>=from&&x.CreatedAt<to).ToListAsync();return projects.GroupBy(x=>new{x.CreatedAt.Year,Quarter=(x.CreatedAt.Month-1)/3+1}).Select(g=>Row(("Year",g.Key.Year.ToString()),("Quarter",$"Q{g.Key.Quarter}"),("Created",g.Count().ToString()),("Completed",g.Count(x=>x.Status=="Completed").ToString()),("Ongoing",g.Count(x=>x.Status=="Ongoing").ToString()),("Delayed",g.Count(x=>x.Status=="Delayed"||(x.EndDate<DateTime.UtcNow&&x.Status!="Completed")).ToString()),("Archived",g.Count(x=>x.IsArchived).ToString()),("AverageProgress",Math.Round(g.Average(x=>x.ProgressPercentage),2).ToString()))).ToList();}
  case "attendance-summary":{var q=_db.Attendances.AsNoTracking().Include(x=>x.User).ThenInclude(x=>x!.Department).Where(x=>x.AttendanceDate>=from&&x.AttendanceDate<to&&x.User!=null&&x.User.Role!="Admin");if(query.DepartmentId.HasValue)q=q.Where(x=>x.User!.DepartmentId==query.DepartmentId);var rows=await q.ToListAsync();return rows.GroupBy(x=>new{Department=x.User!.Department!=null?x.User.Department.Name:"Unassigned",x.AttendanceStatus}).Select(g=>Row(("Department",g.Key.Department),("Status",g.Key.AttendanceStatus),("Records",g.Count().ToString()),("AverageHours",Math.Round(g.Average(x=>x.TotalHours),2).ToString()),("MissingCheckout",g.Count(x=>x.CheckInTime.HasValue&&!x.CheckOutTime.HasValue).ToString()))).ToList();}
  case "leave-summary":{var q=_db.Leaves.AsNoTracking().Include(x=>x.User).ThenInclude(x=>x!.Department).Where(x=>x.AppliedAt>=from&&x.AppliedAt<to&&x.User!=null&&x.User.Role!="Admin");if(query.DepartmentId.HasValue)q=q.Where(x=>x.User!.DepartmentId==query.DepartmentId);var rows=await q.ToListAsync();return rows.GroupBy(x=>new{Department=x.User!.Department!=null?x.User.Department.Name:"Unassigned",x.Status}).Select(g=>Row(("Department",g.Key.Department),("Status",g.Key.Status),("Requests",g.Count().ToString()))).ToList();}
  case "calendar-summary":{var meetings=await _db.CalendarEvents.AsNoTracking().Where(x=>x.StartTime>=from&&x.StartTime<to).ToListAsync();var holidays=await _db.CompanyHolidays.AsNoTracking().Where(x=>x.HolidayDate>=from&&x.HolidayDate<to).ToListAsync();return new(){Row(("Category","Meetings"),("Scheduled",meetings.Where(x=>x.Status=="Scheduled").Select(x=>x.MeetingGroupId).Distinct().Count().ToString()),("Completed",meetings.Where(x=>x.Status=="Completed").Select(x=>x.MeetingGroupId).Distinct().Count().ToString()),("Cancelled",meetings.Where(x=>x.Status=="Cancelled").Select(x=>x.MeetingGroupId).Distinct().Count().ToString())),Row(("Category","Holidays"),("Scheduled",holidays.Count(x=>x.IsActive).ToString()),("Completed","0"),("Cancelled",holidays.Count(x=>!x.IsActive).ToString()))};}
  case "system-activity":case "audit-logs":{var rows=await _db.AuditLogs.AsNoTracking().Where(x=>x.Timestamp>=from&&x.Timestamp<to).OrderByDescending(x=>x.Timestamp).Take(10000).ToListAsync();return rows.Select(x=>Row(("TimestampUtc",x.Timestamp.ToString("O")),("ActorUserId",x.ActorUserId?.ToString()),("Action",x.Action),("EntityType",x.EntityType),("EntityId",x.EntityId),("Result",x.Result),("CorrelationId",x.CorrelationId))).ToList();}
  default:throw new ArgumentException("Unsupported Admin report type");}}
 private static Dictionary<string,string?> Row(params(string Key,string? Value)[] values)=>values.ToDictionary(x=>x.Key,x=>x.Value);
}